"""Generate docs/data_dictionary.md and docs/role_permission_matrix.md from the live registry.
   odoo shell -d <db> --addons-path=... < migration/dump_docs.py   (run from the repo root)"""
import collections

out = ['# Data dictionary (generated from the installed registry)\n',
       'Generated by `migration/dump_docs.py`. Do not edit by hand.\n']
models = env['ir.model'].search([('model', '=like', 'ei.%'), ('transient', '=', False)], order='model')
for m in models:
    out.append('\n## `%s` - %s\n' % (m.model, m.name))
    out.append('| Field | Type | Req | Stored | Description |\n|---|---|---|---|---|')
    for f in env['ir.model.fields'].search([('model_id', '=', m.id)], order='name'):
        if f.name in ('id', 'create_uid', 'create_date', 'write_uid', 'write_date', 'display_name', '__last_update') or f.name.startswith(('message_', 'activity_', 'website_')):
            continue
        out.append('| %s | %s | %s | %s | %s |' % (f.name, f.ttype + (' -> ' + f.relation if f.relation else ''),
                   'Y' if f.required else '', 'Y' if f.store else '', (f.field_description or '').replace('|', '/')))
open('docs/data_dictionary.md', 'w').write('\n'.join(out) + '\n')

privs = env['res.groups.privilege'].search([('name', 'ilike', 'Export International')])
groups = env['res.groups'].search([('privilege_id', 'in', privs.ids)], order='privilege_id, name')
md = ['# Role and permission matrix (generated)\n', 'Generated by `migration/dump_docs.py`.\n',
      '## Groups and what they imply\n', '| Group | Area | Implies |', '|---|---|---|']
for g in groups:
    md.append('| %s | %s | %s |' % (g.name, g.privilege_id.name.replace('Export International - ', ''),
                                   ', '.join(sorted(i.name for i in g.implied_ids))))
md += ['\n## Model access (Odoo 20 ir.access: c=create r=read u=update d=delete) by group\n']
acc = collections.defaultdict(list)
for a in env['ir.access'].search([('group_id', 'in', groups.ids), ('model_id.model', '=like', 'ei.%')]):
    acc[a.model_id.model].append(a)
for model in sorted(acc):
    md.append('\n### `%s`\n\n| Group | Operations |\n|---|---|' % model)
    for a in sorted(acc[model], key=lambda a: a.group_id.name):
        md.append('| %s | %s |' % (a.group_id.name, a.operation))
md += ['\n## Restrictions without a group (company scoping etc.)\n', '| Name | Model | Operations | Domain |', '|---|---|---|---|']
for r in env['ir.access'].search([('group_id', '=', False), ('model_id.model', '=like', 'ei.%')], order='name'):
    md.append('| %s | %s | %s | `%s` |' % (r.name, r.model_id.model, r.operation, r.domain))
md += ['\n## Controlled actions that check a group or a second person (maker-checker)\n',
       'See each module\'s tests: importer != approver != poster (bank), maker != checker (cash, contracts, DAs, orders, liftings, '
       'intake overrides, formulas, reconciliation sign-off, LC verification, legacy mapping). Parameters that relax separation: '
       '`ei_legacy_master.enforce_maker_checker`, `ei_bank_operations.strict_separation`.']
open('docs/role_permission_matrix.md', 'w').write('\n'.join(md) + '\n')

# Screen inventory: every menu of the application, what it opens, and which roles reach it (menu groups and read access together).
root = env.ref('ei_legacy_master.menu_ei_root')
roles = groups | env['res.groups'].search([('id', 'in', [env.ref(x).id for x in (
    'account.group_account_user', 'account.group_account_manager', 'account.group_account_invoice') if env.ref(x, raise_if_not_found=False)])])


def who(menu, model):
    out = []
    for g in roles:
        if menu.group_ids and not (menu.group_ids & (g | g.all_implied_ids)):
            continue
        if model and model in env and not env['ir.access'].search_count([('model_id.model', '=', model), ('operation', 'like', 'r'),
                                                                          ('group_id', 'in', (g | g.all_implied_ids).ids)]):
            continue
        out.append(g.name)
    return ', '.join(sorted(out)) or '(administrator only)'


inv = ['# Screen inventory (generated)\n', 'Generated by `migration/dump_docs.py` from the installed menus, actions and access rules. '
       '"Who" lists the roles whose menu rights and read access both allow the screen; record rules (company, own records) apply on top.\n',
       '| Menu | Opens | Model | Who |', '|---|---|---|---|']
for m in env['ir.ui.menu'].search([('id', 'child_of', root.id)], order='parent_path'):
    act = m.action
    model = getattr(act, 'res_model', False) if act else False
    kind = {'ir.actions.act_window': 'list/form', 'ir.actions.client': 'screen', 'ir.actions.server': 'action'}.get(act._name, '') if act else 'menu'
    path = m.complete_name.replace('Export International/', '').replace('/', ' > ')
    inv.append('| %s | %s | %s | %s |' % (path, kind, model or '', who(m, model) if act else ''))
open('docs/screen_inventory.md', 'w').write('\n'.join(inv) + '\n')
print('ok', len(models), 'models', len(groups), 'groups')
